import tiktoken

MAX_HISTORY_TOKENS = 100_000   # leave headroom below the model's actual limit
encoding = tiktoken.get_encoding("cl100k_base")
conversation = [{"role": "system", "content": "You are a helpful assistant."}]

def count_tokens(messages):
    return sum(len(encoding.encode(m["content"])) for m in messages)

def trim_history():
    # always keep the system message; drop oldest user/assistant turns first
    while count_tokens(conversation) > MAX_HISTORY_TOKENS and len(conversation) > 1:
        conversation.pop(1)

def send_turn(user_text, call_model):
    conversation.append({"role": "user", "content": user_text})
    trim_history()
    reply = call_model(conversation)
    conversation.append({"role": "assistant", "content": reply})
    return reply

