def generate(prompt_tokens, model, max_new_tokens=100, eos_token_id=50256):
    tokens = list(prompt_tokens)
    for _ in range(max_new_tokens):
        logits = model.forward(tokens)          # one logit per vocabulary entry
        probs = softmax(logits[-1])              # distribution for the NEXT token only
        next_token = argmax(probs)               # greedy choice, for simplicity
        if next_token == eos_token_id:
            break
        tokens.append(next_token)                # feeds back in as input next iteration
    return tokens[len(prompt_tokens):]

